+            <h5 class="mb-0">Change Password</h5>
+            <span>@(PasswordPanelOpen ? "▲" : "▼")</span>
+        </div>
+        @if (PasswordPanelOpen)
+        {
+            <div class="card-body">
+                <div class="mb-3">
+                    <label class="form-label">Current Password</label>
+                    <input type="password" class="form-control" @bind="CurrentPassword" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">New Password</label>
+                    <input type="password" class="form-control" @bind="NewPassword" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Confirm New Password</label>
+                    <input type="password" class="form-control" @bind="ConfirmPassword" />
+                </div>
+                <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@IsChangingPassword">
+                    @if (IsChangingPassword)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1"></span>
+                    }
+                    Update Password
+                </button>
+            </div>
+        }
+    </div>
+
+    <!-- Two-Factor Authentication -->
+    <div class="card mb-4">
+        <div class="card-body">
+            <div class="d-flex justify-content-between align-items-center">
+                <div>
+                    <h5 class="mb-1">Two-Factor Authentication</h5>
+                    <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
+                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
+                    </span>
+                </div>
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" @bind="TwoFactorEnabled" style="transform: scale(1.3);" />
+                </div>
+            </div>
+            @if (Settings?.LastPasswordChange is not null)
+            {
+                <small class="text-muted d-block mt-2">
+                    Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
+                </small>
+            }
+        </div>
+    </div>
+
+    <!-- Active Sessions -->
+    <div class="card mb-4">
+        <div class="card-header">
+            <h5 class="mb-0">Active Sessions</h5>
+        </div>
+        <div class="card-body p-0">
+            <div class="table-responsive">
+                <table class="table table-hover mb-0">
+                    <thead>
+                        <tr>
+                            <th>Device</th>
+                            <th>Location</th>
+                            <th>Last Active</th>
+                            <th></th>
+                        </tr>
+                    </thead>
+                    <tbody>
+                        @if (Sessions is not null)
+                        {
+                            @foreach (var session in Sessions)
+                            {
+                                <tr>
+                                    <td>@session.Device</td>
+                                    <td>@session.Location</td>
+                                    <td>@session.LastActive.ToString("g")</td>
+                                    <td>
+                                        @if (session != Sessions.FirstOrDefault())
+                                        {
+                                            <button class="btn btn-sm btn-outline-danger"
+                                                    @onclick="() => ConfirmRevoke(session)">
+                                                Revoke
+                                            </button>
+                                        }
+                                        else
+                                        {
+                                            <span class="badge bg-info">Current</span>
+                                        }
+                                    </td>
+                                </tr>
+                            }
+                        }
+                    </tbody>
+                </table>
+            </div>
+        </div>
+    </div>
+
+    <!-- Revoke Confirmation Dialog -->
+    @if (SessionToRevoke is not null)
+    {
+        <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
+            <div class="modal-dialog">
+                <div class="modal-content">
+                    <div class="modal-header">
+                        <h5 class="modal-title">Confirm Session Revocation</h5>
+                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
+                    </div>
+                    <div class="modal-body">
+                        <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> from <strong>@SessionToRevoke.Location</strong>?</p>
+                    </div>
+                    <div class="modal-footer">
+                        <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
+                        <button type="button" class="btn btn-danger" @onclick="RevokeConfirmedAsync" disabled="@IsRevoking">
+                            @if (IsRevoking)
+                            {
+                                <span class="spinner-border spinner-border-sm me-1"></span>
+                            }
+                            Revoke Session
+                        </button>
+                    </div>
+                </div>
+            </div>
+        </div>
+    }
+</div>
+
+@code {
+    [Parameter] public SecuritySettings? Settings { get; set; }
+    [Parameter] public EventCallback<string> OnChangePassword { get; set; }
+    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
+
+    private bool PasswordPanelOpen { get; set; }
+    private string CurrentPassword { get; set; } = "";
+    private string NewPassword { get; set; } = "";
+    private string ConfirmPassword { get; set; } = "";
+    private bool TwoFactorEnabled { get; set; }
+    private List<ActiveSession>? Sessions { get; set; }
+    private ActiveSession? SessionToRevoke { get; set; }
+    private bool IsChangingPassword { get; set; }
+    private bool IsRevoking { get; set; }
+    private string? StatusMessage { get; set; }
+    private bool IsError { get; set; }
+
+    private bool _initialized;
+
+    protected override void OnParametersSet()
+    {
+        if (Settings is not null && !_initialized)
+        {
+            TwoFactorEnabled = Settings.TwoFactorEnabled;
+            Sessions = new List<ActiveSession>(Settings.Sessions);
+            _initialized = true;
+        }
+    }
+
+    private async Task ChangePasswordAsync()
+    {
+        StatusMessage = null;
+
+        if (string.IsNullOrWhiteSpace(NewPassword))
+        {
+            StatusMessage = "New password cannot be empty.";
+            IsError = true;
+            return;
+        }
+
+        if (NewPassword != ConfirmPassword)
+        {
+            StatusMessage = "New password and confirmation do not match.";
+            IsError = true;
+            return;
+        }
+
+        IsChangingPassword = true;
+        await OnChangePassword.InvokeAsync($"{CurrentPassword}||{NewPassword}");
+        IsChangingPassword = false;
+        CurrentPassword = "";
+        NewPassword = "";
+        ConfirmPassword = "";
+        StatusMessage = "Password changed successfully!";
+        IsError = false;
+        PasswordPanelOpen = false;
+    }
+
+    private void ConfirmRevoke(ActiveSession session)
+    {
+        SessionToRevoke = session;
+    }
+
+    private void CancelRevoke()
+    {
+        SessionToRevoke = null;
+    }
+
+    private async Task RevokeConfirmedAsync()
+    {
+        if (SessionToRevoke is null) return;
+        IsRevoking = true;
+        await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
+        Sessions?.Remove(SessionToRevoke);
+        IsRevoking = false;
+        SessionToRevoke = null;
+        StatusMessage = "Session revoked successfully.";
+        IsError = false;
+    }
+}
