@namespace sv_c48bb95357e24a82b49712c34fe1e713.Components.Pages.Settings

<div class="appearance-section">
    <h3 class="mb-4">Appearance Settings</h3>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            Appearance settings saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <!-- Theme -->
            <div class="card mb-3">
                <div class="card-body">
                    <h5 class="card-title">Theme</h5>
                    <div class="d-flex gap-3">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(SelectedTheme == theme)"
                                       @onchange="() => SelectedTheme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>
            </div>

            <!-- Font Size -->
            <div class="card mb-3">
                <div class="card-body">
                    <h5 class="card-title">Font Size</h5>
                    <div class="d-flex gap-3">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"size-{size}")" value="@size"
                                       checked="@(SelectedFontSize == size)"
                                       @onchange="() => SelectedFontSize = size" />
                                <label class="form-check-label" for="@($"size-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>
            </div>

            <!-- Language -->
            <div class="card mb-3">
                <div class="card-body">
                    <h5 class="card-title">Language</h5>
                    <select class="form-select" @bind="SelectedLanguage">
                        <option value="en">English</option>
                        <option value="es">Spanish</option>
                        <option value="fr">French</option>
                        <option value="de">German</option>
                        <option value="ja">Japanese</option>
                        <option value="zh">Chinese</option>
                    </select>
                </div>
            </div>

            <!-- Compact Mode -->
            <div class="card mb-3">
                <div class="card-body">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                    <small class="text-muted">Reduces spacing and padding throughout the interface.</small>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @if (IsSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <div class="card">
                <div class="card-header">
                    <h5 class="mb-0">Preview</h5>
                </div>
                <div class="card-body @PreviewBackgroundClass" style="@PreviewStyle">
                    <div class="@(CompactMode ? "p-1" : "p-3")">
                        <h6 class="@PreviewTextClass" style="@PreviewFontStyle">Sample Heading</h6>
                        <p class="@PreviewTextClass mb-2" style="@PreviewFontStyle">
                            This is how your content will look with the selected appearance settings.
                        </p>
                        <button class="btn btn-sm @PreviewButtonClass">Sample Button</button>
                        <div class="mt-2">
                            <span class="badge @PreviewBadgeClass">Status</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme { get; set; } = "Light";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "en";
    private bool CompactMode { get; set; }
    private bool IsSaving { get; set; }
    private bool ShowSuccess { get; set; }

    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewBackgroundClass => SelectedTheme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };

    private string PreviewTextClass => SelectedTheme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string PreviewButtonClass => SelectedTheme switch
    {
        "Dark" => "btn-light",
        _ => "btn-primary"
    };

    private string PreviewBadgeClass => SelectedTheme switch
    {
        "Dark" => "bg-light text-dark",
        _ => "bg-primary"
    };

    private string PreviewStyle => SelectedTheme == "Dark"
        ? "min-height: 200px; border: 1px solid #444;"
        : "min-height: 200px; border: 1px solid #dee2e6;";

    private string PreviewFontStyle => SelectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
    }
}

