@using sv_c48bb95357e24a82b49712c34fe1e713.Services
@using sv_c48bb95357e24a82b49712c34fe1e713.Components.Pages.Settings
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="settings-sidebar">
        <SettingsNavigation ActiveSection="@ActiveSection" OnSectionChanged="SetActiveSection" />
    </div>

    <div class="settings-content">
        @if (IsLoading)
        {
            <div class="d-flex justify-content-center align-items-center" style="min-height: 300px;">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationsAsync" />
                    break;
                case "Security":
                    <SecuritySection Settings="@_securitySettings"
                                     OnChangePassword="HandleChangePasswordAsync"
                                     OnRevokeSession="HandleRevokeSessionAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@_appearanceSettings" OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; }

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _securitySettings;
    private AppearanceSettings? _appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync();
    }

    private async Task SetActiveSection(string section)
    {
        ActiveSection = section;
        await LoadSectionDataAsync();
    }

    private async Task LoadSectionDataAsync()
    {
        IsLoading = true;
        StateHasChanged();

        switch (ActiveSection)
        {
            case "Profile":
                _profile = await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                _appearanceSettings = await SettingsService.GetAppearanceAsync();
                break;
        }

        IsLoading = false;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task HandleChangePasswordAsync(string passwordData)
    {
        var parts = passwordData.Split("||", 2);
        await SettingsService.ChangePasswordAsync(parts[0], parts[1]);
    }

    private async Task HandleRevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 100px);
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 1rem;
    background-color: #f8f9fa;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-nav .nav-link {
    border-radius: 0.375rem;
    margin-bottom: 0.25rem;
    color: #495057;
    transition: all 0.15s ease-in-out;
}

.settings-nav .nav-link:hover {
    background-color: #e9ecef;
}

.settings-nav .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

